# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), условие сверено с текстом учебника (№4.41, 4.44)"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_§4_4_41_б", r"в учебнике $y=\frac{2}{x^{25}}$ (OCR превратил в $\left(\frac2x\right)^{25}$); для учебного условия ключ $-\frac{50}{x^{26}}$ верен, для искажённого было бы $-\frac{25\cdot2^{25}}{x^{26}}$",
  q=r"Для любого $x \neq 0$ найдите производную функции: $y = \dfrac{2}{x^{25}}$")
E("G11_TB_§4_4_44_з", r"в учебнике $f(x)=\frac{\ln x}{\ln 10}$ (OCR превратил в $\ln\frac{x}{\ln10}$, производная которого $\frac1x$, а не ключ $\frac1{x\ln10}$); ключ и дистракторы относятся к учебному условию",
  q=r"Укажите, при каких значениях $x$ функция $f(x)$ имеет производную, и найдите эту производную, если: $f(x)=\dfrac{\ln x}{\ln 10}$")
E("G11_TB_§4_4_44_и", r"в учебнике $f(x)=\frac{\lg x}{\lg 2}$ (OCR превратил в $\lg\frac{x}{\lg2}$, производная которого $\frac1{x\ln10}$, а не ключ $\frac1{x\ln10\lg2}$); ключ и дистракторы относятся к учебному условию",
  q=r"Укажите, при каких значениях $x$ функция $f(x)$ имеет производную, и найдите эту производную, если: $f(x)=\dfrac{\lg x}{\lg 2}$")
